/// <summary>
/// Kleber validate cust address request contract
/// </summary>
[DataContractAttribute]
class METKleberValidateCustAddressRequestContract
{
    LogisticsAddressStreet addressLine1;
    LogisticsAddressCityName locality;
    LogisticsAddressStateId state;
    LogisticsAddressZipCodeId postcode;
    str requestId, departmentCode;

}

